<?php

declare(strict_types=1);

namespace Tests\Unit;

use App\Services\Audit\AuditHash;
use InvalidArgumentException;
use JsonException;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;

final class AuditHashTest extends TestCase
{
    // Independently precomputed SHA-256 fixtures, not generated by AuditHash.
    private const LEGACY_HASH = 'bf8bba9f60e5828eb9ae2d4e10dcdcc829a8bc783ad58e6ac25906b259a365ac';
    private const V2_HASH = 'b93769bdd774b0429f247816004530195f7eee9c29c160a36b85935f0f56340e';

    private static function event(array $overrides = []): array
    {
        return array_replace([
            'id' => 10,
            'hash_version' => 2,
            'tenant_id' => 7,
            'prev_hash' => AuditHash::GENESIS,
            'event_type' => 'encounter.updated',
            'entity_type' => 'encounter',
            'entity_id' => '42',
            'actor_user_id' => null,
            'actor_role' => 'nurse',
            'actor_ip' => '192.0.2.10',
            'action' => 'update',
            'occurred_at' => '2026-01-02 03:04:05',
            'payload_json' => '{"note":"café/a|b"}',
        ], $overrides);
    }

    private static function signed(array $overrides = []): array
    {
        $event = self::event($overrides);
        $event['curr_hash'] = AuditHash::compute($event);

        return $event;
    }

    private static function chain(array $versions = [1, 2, 2]): array
    {
        $events = [];
        $previous = AuditHash::GENESIS;
        foreach ($versions as $index => $version) {
            $event = self::signed([
                'id' => ($index + 1) * 10,
                'hash_version' => $version,
                'prev_hash' => $previous,
            ]);
            $events[] = $event;
            $previous = $event['curr_hash'];
        }

        return $events;
    }

    private function assertBroken(array $events, int $count, int|string|null $id, int $tenantId = 7): void
    {
        self::assertSame(
            ['valid' => false, 'verified_count' => $count, 'broken_id' => $id],
            AuditHash::verify($events, $tenantId)
        );
    }

    public function testLegacyHashMatchesExactPreCutoverBytes(): void
    {
        $event = self::event(['hash_version' => 1]);
        // Literal old implode representation pins delimiters, system fallback and UTF-8 bytes.
        $bytes = str_repeat('0', 64)
            . '|encounter.updated|encounter|42|system|2026-01-02 03:04:05|{"note":"café/a|b"}';
        self::assertSame(self::LEGACY_HASH, hash('sha256', $bytes));
        self::assertSame(self::LEGACY_HASH, AuditHash::compute($event));
    }

    public function testV2HashPinsFormatMarkerAndExactJsonRepresentation(): void
    {
        $bytes = '{"format":"humus.audit.v2","hash_version":2,"tenant_id":7,"prev_hash":"'
            . str_repeat('0', 64)
            . '","event_type":"encounter.updated","entity_type":"encounter","entity_id":"42",'
            . '"actor_user_id":null,"actor_role":"nurse","actor_ip":"192.0.2.10","action":"update",'
            . '"occurred_at":"2026-01-02 03:04:05","payload_json":"{\\"note\\":\\"café/a|b\\"}"}';
        self::assertSame(self::V2_HASH, hash('sha256', $bytes));
        self::assertSame(self::V2_HASH, AuditHash::compute(self::event()));
    }

    public function testMissingLegacyVersionDefaultsToOneAndMixedChainIsValid(): void
    {
        $events = self::chain();
        unset($events[0]['hash_version']);
        self::assertSame(1, AuditHash::version($events[0]));
        self::assertSame(self::LEGACY_HASH, AuditHash::compute($events[0]));
        self::assertSame(
            ['valid' => true, 'verified_count' => 3, 'broken_id' => null],
            AuditHash::verify(new \ArrayIterator($events), 7)
        );
    }

    public static function logicalFieldChanges(): iterable
    {
        yield 'tenant' => ['tenant_id', 8];
        yield 'previous hash' => ['prev_hash', str_repeat('a', 64)];
        yield 'event type' => ['event_type', 'encounter.deleted'];
        yield 'entity type' => ['entity_type', 'patient'];
        yield 'entity id' => ['entity_id', '43'];
        yield 'actor user' => ['actor_user_id', 9];
        yield 'actor role' => ['actor_role', 'admin'];
        yield 'actor IP' => ['actor_ip', '192.0.2.11'];
        yield 'action' => ['action', 'delete'];
        yield 'occurred at' => ['occurred_at', '2026-01-02 03:04:06'];
        yield 'payload' => ['payload_json', '{"note":"changed"}'];
    }

    #[DataProvider('logicalFieldChanges')]
    public function testEveryV2LogicalFieldChangeInvalidatesStoredHash(string $field, mixed $value): void
    {
        $event = self::signed();
        $event[$field] = $value;
        self::assertNotSame($event['curr_hash'], AuditHash::compute($event));
        $this->assertBroken([$event], 0, 10);
    }

    public static function legacyOmissions(): iterable
    {
        yield 'tenant' => ['tenant_id', 8];
        yield 'action' => ['action', 'delete'];
        yield 'role' => ['actor_role', 'admin'];
        yield 'IP' => ['actor_ip', '192.0.2.11'];
    }

    #[DataProvider('legacyOmissions')]
    public function testLegacyOmissionsRemainUnprotectedByTheHash(string $field, mixed $value): void
    {
        $event = self::signed(['hash_version' => 1]);
        $event[$field] = $value;
        self::assertSame(self::LEGACY_HASH, AuditHash::compute($event));
        // Tenant isolation is a verifier check, not legacy cryptographic binding.
        self::assertTrue(AuditHash::verify([$event], (int) $event['tenant_id'])['valid']);
        if ($field === 'tenant_id') {
            $this->assertBroken([$event], 0, 10);
        }
    }

    public function testForkReportsFirstRowWhoseParentIsNotThePreviousRow(): void
    {
        $events = self::chain();
        $events[2]['prev_hash'] = $events[0]['curr_hash'];
        $events[2]['curr_hash'] = AuditHash::compute($events[2]);
        $this->assertBroken($events, 2, 30);
    }

    public function testMiddleDeletionReportsTheNextSurvivingRow(): void
    {
        $events = self::chain();
        unset($events[1]);
        $this->assertBroken($events, 1, 30);
    }

    public function testReorderingReportsFirstOutOfChainRow(): void
    {
        $events = self::chain();
        $this->assertBroken([$events[0], $events[2], $events[1]], 1, 30);
    }

    public function testVersionDowngradeFailsEvenWithRecomputedLegacyHash(): void
    {
        $this->assertBroken(self::chain([1, 2, 1]), 2, 30);
    }

    public function testChangingV2VersionToOneInvalidatesItsStoredHash(): void
    {
        $event = self::signed();
        $event['hash_version'] = 1;
        self::assertNotSame($event['curr_hash'], AuditHash::compute($event));
        $this->assertBroken([$event], 0, 10);
    }

    public static function unknownVersions(): iterable
    {
        foreach ([0, 3, 'v2', '02', true, 2.0] as $version) {
            yield [ $version ];
        }
    }

    #[DataProvider('unknownVersions')]
    public function testUnknownVersionReportsBrokenIdAndComputeRejectsIt(mixed $version): void
    {
        $events = self::chain();
        $events[1]['hash_version'] = $version;
        $this->assertBroken($events, 1, 20);
        $this->expectException(InvalidArgumentException::class);
        AuditHash::compute($events[1]);
    }

    public function testLegacyDelimiterCollisionIsDistinguishedByV2(): void
    {
        $left = self::event(['event_type' => 'a|b', 'entity_type' => 'c']);
        $right = self::event(['event_type' => 'a', 'entity_type' => 'b|c']);
        self::assertSame(
            AuditHash::compute(array_replace($left, ['hash_version' => 1])),
            AuditHash::compute(array_replace($right, ['hash_version' => 1]))
        );
        self::assertNotSame(AuditHash::compute($left), AuditHash::compute($right));
    }

    public function testV2DistinguishesPayloadArrayStringAndDelimitedString(): void
    {
        self::assertNotSame(
            AuditHash::compute(self::event(['payload_json' => '["a","b"]'])),
            AuditHash::compute(self::event(['payload_json' => 'a|b']))
        );
    }

    public function testV2PreservesNullVersusEmptyRoleAndPayload(): void
    {
        foreach (['actor_role', 'payload_json', 'actor_ip'] as $field) {
            $null = self::signed([$field => null]);
            $empty = array_replace($null, [$field => '']);
            self::assertNotSame($null['curr_hash'], AuditHash::compute($empty), $field);
            $this->assertBroken([$empty], 0, 10);
        }
    }

    public function testLegacyNullAndEmptyPayloadRemainIndistinguishable(): void
    {
        self::assertSame(
            AuditHash::compute(self::event(['hash_version' => 1, 'payload_json' => null])),
            AuditHash::compute(self::event(['hash_version' => 1, 'payload_json' => '']))
        );
        self::assertSame(
            AuditHash::compute(self::event(['hash_version' => 1, 'actor_role' => null])),
            AuditHash::compute(self::event(['hash_version' => 1, 'actor_role' => '']))
        );
    }

    public function testNumericDatabaseStringsHaveStableHashesAndVerify(): void
    {
        foreach ([1, 2] as $version) {
            $event = self::signed(['hash_version' => $version, 'actor_user_id' => 9, 'entity_id' => 42]);
            $databaseRow = $event;
            foreach (['id', 'hash_version', 'tenant_id', 'actor_user_id', 'entity_id'] as $field) {
                $databaseRow[$field] = (string) $databaseRow[$field];
            }
            self::assertSame($event['curr_hash'], AuditHash::compute($databaseRow));
            self::assertSame(
                ['valid' => true, 'verified_count' => 1, 'broken_id' => null],
                AuditHash::verify([$databaseRow], 7)
            );
        }
    }

    public function testInvalidUtf8ThrowsOnComputeAndFailsVerificationSafely(): void
    {
        $events = self::chain();
        $events[1]['payload_json'] = "\xB1\x31";
        $this->assertBroken($events, 1, 20);
        $this->expectException(JsonException::class);
        AuditHash::compute($events[1]);
    }

    public function testIdsAreOrderedButAreNotCryptographicallyBound(): void
    {
        $events = self::chain([2, 2, 2]);
        foreach ($events as &$event) {
            $event['id'] += 100;
            self::assertSame($event['curr_hash'], AuditHash::compute($event));
        }
        unset($event);
        self::assertTrue(AuditHash::verify($events, 7)['valid']);
        $events[1]['id'] = $events[0]['id'];
        $this->assertBroken($events, 1, 110);
        $events[1]['id'] = 109;
        $this->assertBroken($events, 1, 109);
    }

    public static function actorBoundaryFixtures(): iterable
    {
        // Independently precomputed with JSON actor IDs encoded as decimal strings.
        yield ['0', '70b8cc5119d8bb9efb47fd59b5db921b9e2ecbad29deb628623e7b21008196ac'];
        yield ['9223372036854775807', '3aa42a903affb8540ee4b51670ba9e19bd312770035d565c8615241e2825847e'];
        yield ['9223372036854775808', '82036b25a7a44f3865c19690bc27b62429714a6e45ae4a78928dbda5de484973'];
        yield ['9223372036854775809', '429ffd6f45fd6a9493ff6541d30310441a551997561827a615db2c064019411c'];
        yield ['18446744073709551614', '5aa195211d8cb4c3386b1bcb7038623e5b08c939121df0d0493503d1f0e8de0b'];
        yield ['18446744073709551615', 'fdeba14ee577150929d508a7c6b6519244b0fe870332a9f2a1532062e74c3638'];
    }

    #[DataProvider('actorBoundaryFixtures')]
    public function testV2ActorBoundaryFixturesAreLossless(string $actor, string $hash): void
    {
        $event = self::event(['actor_user_id' => $actor, 'curr_hash' => $hash]);
        self::assertSame($hash, AuditHash::compute($event));
        self::assertTrue(AuditHash::verify([$event], 7)['valid']);
        self::assertSame($hash, AuditHash::compute(array_replace($event, ['actor_user_id' => '00' . $actor])));
        if (strlen($actor) < strlen((string) PHP_INT_MAX)
            || (strlen($actor) === strlen((string) PHP_INT_MAX) && strcmp($actor, (string) PHP_INT_MAX) <= 0)) {
            self::assertSame($hash, AuditHash::compute(array_replace($event, ['actor_user_id' => (int) $actor])));
        }
    }

    public function testAdjacentBigActorIdsCannotReplaceEachOther(): void
    {
        $event = self::signed(['actor_user_id' => '18446744073709551614']);
        $event['actor_user_id'] = '18446744073709551615';
        self::assertNotSame($event['curr_hash'], AuditHash::compute($event));
        $this->assertBroken([$event], 0, 10);
        self::assertNotSame(
            AuditHash::compute(self::event(['actor_user_id' => null])),
            AuditHash::compute(self::event(['actor_user_id' => 0]))
        );
    }

    public static function invalidUnsignedIds(): iterable
    {
        yield 'empty' => [''];
        yield 'negative integer' => [-1];
        yield 'negative string' => ['-1'];
        yield 'float' => [9.0];
        yield 'overflow float' => [18446744073709551616.0];
        yield 'out of range' => ['18446744073709551616'];
        yield 'very long' => [str_repeat('9', 100)];
        yield 'plus sign' => ['+1'];
        yield 'leading whitespace' => [' 1'];
        yield 'trailing newline' => ["1\n"];
        yield 'decimal point' => ['1.0'];
        yield 'exponent' => ['1e3'];
        yield 'non digit' => ['12x'];
        yield 'boolean' => [true];
        yield 'array' => [[]];
    }

    #[DataProvider('invalidUnsignedIds')]
    public function testInvalidActorIdsFailClosedAndComputeThrows(mixed $actor): void
    {
        $event = self::signed();
        $event['actor_user_id'] = $actor;
        $this->assertBroken([$event], 0, 10);
        $this->expectException(InvalidArgumentException::class);
        AuditHash::compute($event);
    }

    #[DataProvider('invalidUnsignedIds')]
    public function testInvalidRowIdsFailClosedWithoutLossyBrokenId(mixed $id): void
    {
        $event = self::signed(['id' => $id]);
        $this->assertBroken([$event], 0, null);
    }

    public function testNullRowIdFailsClosed(): void
    {
        $this->assertBroken([self::signed(['id' => null])], 0, null);
    }

    public static function orderedRowIds(): iterable
    {
        yield 'decimal length transition' => [['9', '10', '100']];
        yield 'signed boundary' => [['9223372036854775807', '9223372036854775808', '9223372036854775809']];
        yield 'unsigned maximum' => [['18446744073709551613', '18446744073709551614', '18446744073709551615']];
    }

    #[DataProvider('orderedRowIds')]
    public function testRowIdsAreOrderedLosslesslyAndMiddleTamperingIsReported(array $ids): void
    {
        $events = self::chain([2, 2, 2]);
        foreach ($ids as $index => $id) {
            $events[$index]['id'] = $id;
            self::assertSame($events[$index]['curr_hash'], AuditHash::compute($events[$index]));
        }
        self::assertSame(
            ['valid' => true, 'verified_count' => 3, 'broken_id' => null],
            AuditHash::verify($events, 7)
        );
        $brokenId = strlen($ids[1]) < strlen((string) PHP_INT_MAX)
            || (strlen($ids[1]) === strlen((string) PHP_INT_MAX) && strcmp($ids[1], (string) PHP_INT_MAX) <= 0)
            ? (int) $ids[1] : $ids[1];
        $tampered = $events;
        $tampered[1]['action'] = 'delete';
        $this->assertBroken($tampered, 1, $brokenId);
        $tampered = $events;
        $tampered[1]['id'] = $ids[0];
        $firstId = strlen($ids[0]) < strlen((string) PHP_INT_MAX)
            || (strlen($ids[0]) === strlen((string) PHP_INT_MAX) && strcmp($ids[0], (string) PHP_INT_MAX) <= 0)
            ? (int) $ids[0] : $ids[0];
        $this->assertBroken($tampered, 1, $firstId);
        $tampered[0]['id'] = $ids[2];
        $this->assertBroken($tampered, 1, $firstId);
    }

    public function testBigMiddleDeletionAndReorderReportExactSurvivingId(): void
    {
        $events = self::chain();
        foreach (['18446744073709551613', '18446744073709551614', '18446744073709551615'] as $index => $id) {
            $events[$index]['id'] = $id;
        }
        $this->assertBroken([$events[0], $events[2]], 1, '18446744073709551615');
        $this->assertBroken([$events[0], $events[2], $events[1]], 1, '18446744073709551615');
    }

    public function testBrokenIdAtPhpIntMaxRemainsAnInteger(): void
    {
        $event = self::signed(['id' => (string) PHP_INT_MAX]);
        $event['action'] = 'delete';
        $this->assertBroken([$event], 0, PHP_INT_MAX);
    }

    public function testEmptyChainIsValid(): void
    {
        self::assertSame(
            ['valid' => true, 'verified_count' => 0, 'broken_id' => null],
            AuditHash::verify([], 7)
        );
    }
}
